Think: Compare recorded line counts with actual wc -l results for each file, log any differences to temp_workspace/discrepancies.txt, and produce a corrected per-file CSV temp_workspace/per_file_lines_corrected.csv (initializing files first).

Act: bash

```bash
awk 'BEGIN{ system("rm -f temp_workspace/discrepancies.txt temp_workspace/per_file_lines_corrected.csv") }
{
 pos = match($0, /,[^,]*$/);
 if(pos){ path = substr($0,1,pos-1); old = substr($0,pos+1); } else { path=$0; old=""; }
 cmd = "wc -l < \"" path "\"";
 cmd | getline actual;
 close(cmd);
 gsub(/^[ \t]+|[ \t]+$/,"",actual);
 if(actual != old){
  print path "," old "," actual >> "temp_workspace/discrepancies.txt";
  print path "," actual >> "temp_workspace/per_file_lines_corrected.csv";
 } else {
  print $0 >> "temp_workspace/per_file_lines_corrected.csv";
 }
}' temp_workspace/per_file_lines.csv
