Think: Create the script file count_peak_logins.sh inside peak_login_task. The script will contain a header, description, placeholders (as comments), and a single awk command (one logical command) that performs parsing, writes extracted_times.txt, invalid_entries.log, peak_times.txt, peak_count.txt, and prints just the integer count. Use a quoted heredoc so awk's $ variables are not expanded during creation.

Act: bash

```bash
cat > peak_login_task/count_peak_logins.sh <<'EOF'
#!/bin/sh
# count_peak_logins.sh
# Description: Count logins between 21:00 and 23:59 (inclusive) from server.log
# INPUT: server.log
# OUTPUT: peak_count.txt
#
# This script extracts timestamps into extracted_times.txt,
# logs malformed lines to invalid_entries.log,
# selects peak-hour timestamps into peak_times.txt,
# writes the integer count to peak_count.txt, and prints the integer.

awk '
BEGIN{
  FS=" ";
  peak=0;
  of_ex="extracted_times.txt";
  of_inv="invalid_entries.log";
  of_peak="peak_times.txt";
  # remove old outputs if present
  system("rm -f " of_ex " " of_inv " " of_peak " peak_count.txt");
}
{
  # match leading timestamp like H:MM or HH:MM
  if (match($0, /^([0-9]{1,2}):([0-9]{2})/, m)) {
    h = m[1] + 0;
    mn = m[2] + 0;
    # write normalized timestamp to extracted_times.txt (pad minutes)
    printf "%d:%02d\n", h, mn >> of_ex;
    # sanity check hour/minute ranges
    if (h >= 0 && h <= 23 && mn >= 0 && mn <= 59) {
      # peak hours 21:00 - 23:59 inclusive
      if (h >= 21 && h <= 23) {
        printf "%d:%02d\n", h, mn >> of_peak;
        peak++;
      }
    } else {
      # invalid numeric ranges
      print $0 >> of_inv;
    }
  } else {
    # does not match expected timestamp pattern
    print $0 >> of_inv;
  }
}
END{
  # write only the integer count to peak_count.txt and print it
  print peak > "peak_count.txt";
  print peak;
}
' server.log
EOF
