Think: Create a detailed listing (raw byte counts and file counts) for /usr and each immediate subdirectory by scanning all files under /usr with find, aggregating in awk, and saving the output to disk_check_workspace/usr_raw_sizes.txt.

Act: bash

```bash
find /usr -printf '%y\t%s\t%p\n' | awk -F '\t' '
{
 type=$1; size=$2+0; path=$3;
 # record any immediate entry under /usr (dir, symlink, file, etc.)
 if (path ~ "^/usr/[^/]+$") dirlist[path]=1;
 if (type=="f") {
   total_bytes+=size; total_files++;
   # determine immediate subdirectory (or /usr itself)
   rest = substr(path,6); # remove "/usr/"
   if (rest=="" || index(rest,"/")==0) top="/usr";
   else { split(rest, a, "/"); top="/usr/"a[1]; }
   sum[top]+=size; cnt[top]++;
 }
}
END {
 # ensure /usr present
 dirlist["/usr"]=1;
 # print header
 print "path\tbytes\tfile_count";
 # print aggregate for /usr (total of all files)
 print "/usr\t" (total_bytes+0) "\t" (total_files+0);
 # print each immediate entry sorted
 n=asorti(dirlist,arr);
 for(i=1;i<=n;i++){
   d=arr[i];
   if (d=="/usr") continue;
   b = (sum[d]+0);
   c = (cnt[d]+0);
   print d "\t" b "\t" c;
 }
}' > disk_check_workspace/usr_raw_sizes.txt
```

